mapper.delete:
delete from
favorite where match_id=#{matchId} and user_id=#{userId} and
match_type=#{matchType}

mapper.select:
SELECT m.*
FROM favorite f
JOIN personal_match m ON m.personal_match_id
= f.match_id
WHERE f.user_id = #{userId}
AND f.match_type = 'Personal'
AND m.deleted = '0'

	AND m.sport = #{sport}


	AND m.status = #{status}


	AND m.match_date >= #{startDate}


	AND m.match_date <= #{endDate}

ORDER BY m.match_date, m.personal_match_id
LIMIT #{size} OFFSET
#{offset}

SELECT COUNT(*)
FROM favorite f
JOIN personal_match m ON
m.personal_match_id = f.match_id
WHERE f.user_id = #{userId}
AND
f.match_type = 'Personal'
AND m.deleted = '0'
 AND m.sport = #{sport} 
 AND m.status = #{status} 
 AND m.match_date >= #{startDate} 
 AND m.match_date <= #{endDate}

SELECT DISTINCT DATE_FORMAT(m.match_date, '%Y-%m-%d')
FROM favorite f
JOIN personal_match m ON m.personal_match_id = f.match_id
WHERE
f.user_id = #{userId}
AND f.match_type = 'Personal'
AND m.deleted = '0'
 AND m.sport = #{sport} 
 AND m.status = #{status}
